    14	// After SIGTERM-ing a timed-out group, wait this long for a graceful exit, then
    15	// SIGKILL the whole group. A CLI that traps/ignores SIGTERM cannot outlive this.
    16	export const KILL_GRACE_MS = 2_000;
    17	
    18	// Spawn a CLI in `cwd`. stdin is IGNORED (= </dev/null): the canary showed Codex
    19	// hangs waiting for stdin EOF otherwise. stdout/stderr captured separately.
    20	//
    21	// `detached: true` makes the child its OWN process-group leader (pgid === pid) so
    22	// a timeout can kill the WHOLE tree, not just the direct child. This is a
    23	// correctness fix, not hygiene: in the 2026-06-12 I Love Coding run a turn ran
    24	// past the cap, SIGTERM hit only the direct child, and a leaked worker kept the
    25	// stdout pipe open — so `close` never fired and the whole debate hung ~45 min at
    26	// ~0 CPU. Group-kill closes the pipe, `close` fires, the turn resolves as timeout,
    27	// and the round proceeds. (Negative pid in process.kill = signal the group.)
    28	function runCli(cmd: string, args: string[], cwd: string, timeoutMs: number): Promise<CliCapture> {
    29	  return new Promise((resolve) => {
    30	    const child = spawn(cmd, args, { cwd, stdio: ["ignore", "pipe", "pipe"], detached: true });
    31	    let stdout = "";
    32	    let stderr = "";
    33	    let timedOut = false;
    34	    let hardTimer: ReturnType<typeof setTimeout> | undefined;
    35	
    36	    // Signal the child's whole process group. ESRCH (group already gone) is benign.
    37	    // We target the group (-pid), never node's own group, because `detached` put
    38	    // the child in its own group — so this can't kill the orchestrator.
    39	    const killGroup = (signal: NodeJS.Signals) => {
    40	      try { if (child.pid) process.kill(-child.pid, signal); }
    41	      catch { /* already dead */ }
    42	    };
    43	
    44	    const timer = setTimeout(() => {
    45	      timedOut = true;
    46	      killGroup("SIGTERM");
    47	      hardTimer = setTimeout(() => killGroup("SIGKILL"), KILL_GRACE_MS); // escalate if ignored
    48	    }, timeoutMs);
    49	
    50	    const finish = (cap: CliCapture) => {
    51	      clearTimeout(timer);
    52	      if (hardTimer) clearTimeout(hardTimer);
    53	      resolve(cap);
    54	    };
    55	
    56	    child.stdout.on("data", (d) => { stdout += d.toString(); });
    57	    child.stderr.on("data", (d) => { stderr += d.toString(); });
    58	    child.on("error", (e) => { finish({ code: null, stdout, stderr: String(e), timedOut }); });
    59	    child.on("close", (code) => { finish({ code, stdout, stderr, timedOut }); });
    60	  });
    61	}
